41: - name: Fail if Continuwuity ReCAPTCHA is only partially configured
42:   ansible.builtin.fail:
43:     msg: >-
44:       You have configured only one of `matrix_continuwuity_config_recaptcha_site_key` and
45:       `matrix_continuwuity_config_recaptcha_private_site_key`. Configure both to enable ReCAPTCHA
46:       registration, or leave both empty to disable it.
47:   when: "(matrix_continuwuity_config_recaptcha_site_key | string | length > 0) != (matrix_continuwuity_config_recaptcha_private_site_key | string | length > 0)"

